// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange - Mock contexts
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [{ id: '1', name: 'X-Wing Parts', price: 99.99 }];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 99.99, clearCart: mockClearCart })
}));
vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The roadmap to order completion', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'REBEL-001' });
  });

  describe('Happy Path - A new hope for our users', () => {
    it('completes full checkout flow', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Yavin Way');
      await user.type(screen.getByLabelText(/city/i), 'Base Four');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Mon Mothma');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review and submit
      expect(screen.getByText(/x-wing parts/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(onComplete).toHaveBeenCalledWith('REBEL-001');
      });
    });
  });

  describe('Form Validation - We must unite against invalid input', () => {
    it('shows shipping validation errors', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert', { name: /street/i })).toHaveTextContent(/required/i);
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip/i)).toBeInTheDocument();
    });
  });

  describe('Error States - The cause requires sacrifice', () => {
    it('handles payment failure gracefully', async () => {
      mockProcessPayment.mockRejectedValue(new Error('Imperial blockade'));
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to review step (abbreviated)
      // ... fill forms ...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/imperial blockade/i);
      });
    });
  });

  describe('Loading States', () => {
    it('disables buttons during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      // Assert buttons disabled, aria-busy present
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });
  });

  describe('Edge Cases - Empty cart', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout />);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });
});
